import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] counts = new int[10];
        for (int i = 0; i < n; i++) {
            long v = sc.nextLong();
            counts[v == 0 ? 0 : (int) (1 + (v - 1) % 9)]++; // digital root
        }
        int best = 0;
        for (int d = 1; d < 10; d++) if (counts[d] >= counts[best]) best = d; // ties go to the larger digit
        System.out.println(best);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(in, &n)
	var counts [10]int
	for i := 0; i < n; i++ {
		var v int
		fmt.Fscan(in, &v)
		if v == 0 {
			counts[0]++
		} else {
			counts[1+(v-1)%9]++ // digital root
		}
	}
	best := 0
	for d := 1; d < 10; d++ {
		if counts[d] >= counts[best] { // ties go to the larger digit
			best = d
		}
	}
	fmt.Println(best)
}
